import json, os

results = {}
for alpha in ['0.0', '1.0']:
    base = f'/root/autodl-tmp/v72_eval/alpha_{alpha}_seed1'
    results[alpha] = {}
    for suite in ['libero_spatial', 'libero_object', 'libero_goal', 'libero_10']:
        path = os.path.join(base, suite, 'eval_info.json')
        if os.path.exists(path):
            with open(path) as f:
                data = json.load(f)
            # Check for suite-level summary first
            if 'suite' in data and 'pc_success' in data.get('suite', {}):
                results[alpha][suite] = data['suite']['pc_success']
            elif 'per_task' in data:
                total_success = 0
                total_episodes = 0
                for task in data['per_task']:
                    successes = task['metrics']['successes']
                    total_success += sum(successes)
                    total_episodes += len(successes)
                results[alpha][suite] = total_success / total_episodes if total_episodes > 0 else 0
        else:
            results[alpha][suite] = 'NOT FOUND'

print('=== v7.2 Eval Results (suite-level success rate) ===')
for alpha, suites in results.items():
    print(f'\nalpha={alpha}:')
    found_suites = []
    for suite, rate in suites.items():
        if isinstance(rate, float):
            print(f'  {suite}: {rate:.4f} ({rate*100:.2f}%)')
            found_suites.append(rate)
        else:
            print(f'  {suite}: {rate}')
    if len(found_suites) == 4:
        avg = sum(found_suites) / 4
        print(f'  4-suite avg: {avg:.4f} ({avg*100:.2f}%)')
    elif len(found_suites) == 3:
        avg3 = sum(found_suites) / 3
        print(f'  3-suite avg (partial): {avg3:.4f} ({avg3*100:.2f}%)')
